import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;

@Service
public class BankTransferService {
    private final AccountRepository accountRepo;

    public BankTransferService(AccountRepository accountRepo) {
        this.accountRepo = accountRepo;
    }

    @Transactional
    public void transfer(Long fromId, Long toId, BigDecimal amount) {
        var from = accountRepo.findByIdForUpdate(fromId).orElseThrow();
        var to = accountRepo.findByIdForUpdate(toId).orElseThrow();

        from.debit(amount);
        to.credit(amount);
        // Both managed changes share one transaction. The explicit locking
        // policy addresses concurrent transfers; @Transactional alone does not.
    }
}

import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;

@Service
public class OrderService {
    private final OrderRepository orderRepo;
    private final InventoryService inventoryService;

    public OrderService(OrderRepository orderRepo, InventoryService inventoryService) {
        this.orderRepo = orderRepo;
        this.inventoryService = inventoryService;
    }

    @Transactional  // Atomicity: all operations or none
    public Order placeOrder(Long productId, int quantity) {
        var order = new Order(productId, quantity);
        orderRepo.save(order);  // Inserted into database

        inventoryService.reduceStock(productId, quantity);  // If this throws exception...
        // ...the entire transaction rolls back automatically
        // Order insert is undone, database returns to pre-transaction state

        return order;  // Only reached if both operations succeed
    }
}

import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;
import java.time.Instant;

@Service
public class PaymentService {
    private final PaymentRepository paymentRepo;

    public PaymentService(PaymentRepository paymentRepo) {
        this.paymentRepo = paymentRepo;
    }

    @Transactional
    public Payment recordPayment(String providerRef, BigDecimal amount) {
        var payment = new Payment(providerRef, amount, Instant.now());
        return paymentRepo.save(payment);
    }
}

// When the transaction manager successfully commits, durability is supplied
// by the database and its configured commit policy—not by the annotation itself.

```sql
BEGIN;

-- Lock both rows in a stable order to coordinate concurrent transfers.
SELECT id, balance
FROM accounts
WHERE id IN (10, 20)
ORDER BY id
FOR UPDATE;

UPDATE accounts
SET balance = balance - 100.00
WHERE id = 10 AND balance >= 100.00;
-- Application must verify that exactly one row was updated.

UPDATE accounts SET balance = balance + 100.00 WHERE id = 20;

INSERT INTO ledger_entries(transfer_id, account_id, amount)
VALUES ('tr-42', 10, -100.00), ('tr-42', 20, 100.00);

COMMIT;
```

The transaction groups local writes. A unique `transfer_id` supports idempotency, while locks and the conditional debit handle concurrency and insufficient funds.

```sql
-- PostgreSQL: choose the level as the transaction begins.
BEGIN TRANSACTION ISOLATION LEVEL READ COMMITTED;

SELECT balance FROM accounts WHERE id = 1;
-- A later statement can see rows committed after this statement's snapshot.

UPDATE accounts
SET balance = balance - 50
WHERE id = 1 AND balance >= 50;

COMMIT;
```

Isolation level and the conditional update solve different parts of the concurrency rule.

```sql
-- One ACID transaction: debit and credit commit together.
START TRANSACTION;
UPDATE accounts SET balance = balance - 100 WHERE id = 1;
UPDATE accounts SET balance = balance + 100 WHERE id = 2;
COMMIT;
```

A BASE-style example needs a distributed product rather than fake SQL: a view counter may accept writes in several regions and expose a temporarily stale total while replicas merge. The exact convergence and conflict rules come from that product's configuration.
